INSERT INTO transfer_ledger VALUES(1,'AVL','2026-summer','영입 지출','만잠비 (Freiburg)',59.5,'5년 계약(2031) — ⭐1티어: Romano 유튜브 2026-07-16 「Manzambi will sign a five-year deal in the next hours」. ⚠️ 릴레이 경유(givemesport 3티어)이고 서명 전 발화다. 구단 공식 발표는 계약연수·이적료 둘 다 미공시(avfc.co.uk 원문 직접 확인). Romano 완료 트윗(2078167033645011305)은 금액만 적는다. 보조: Capology 2031 추정치가 일치.','Sky Sports 「Summer transfer window 2026 — Premier League deals, ins and outs」 2026-08-15 18:44 UK 갱신본 https://www.skysports.com/football/news/11095/13546618/transfer-news-summer-transfer-window-2026-premier-league-deals-ins-and-outs (실제 Chrome 전문 수집 2026-08-16)','⚠️ **완료(공식 발표) 건만**이며 진행 중 루머는 제외했다 — 루헤리·잭슨·완비사카·바르콜라·각포 등은 원장에 없다. ⚠️ **금액은 Sky 표기값**이고 구단 공시가 아니다. 애드온·셀온·급여는 포함되지 않는다 — 실제 회계 계상액과 다르다. ⛔ **임대는 금액 미표기**라 0으로 잡았다(임대료·의무매입은 별도 추적 대상). ⛔ **undisclosed는 0으로 잡지 않고 별도 카운트**한다 — 0으로 합산하면 순지출을 과소·과대 왜곡한다.',5.0);
INSERT INTO transfer_ledger VALUES(2,'AVL','2026-summer','영입 지출','주앙 고메스 (Wolves)',38.0,'5년 계약(2031) — ⚠️⚠️ 2티어까지만 확인: Nicolò Schira 「개인 조건 2031까지 합의」. ⛔ 1티어 미확인 — Sky 13564311·BBC cnvndy7pej9o·Tanswell(The Athletic)·Romano 완료 트윗 (2079145136211075370) 전부 계약연수를 적지 않는다(원문 직접 확인). 구단 공식도 미공시. ⚠️ 별건: 원장 £38.0m은 초기 £34m + 애드온 £4m의 총액이라 상각 분자로 쓸 보장 이적료(£34m)와 다르다 — 분자 정정은 미실시(원장 전 행이 Sky 총액 표기 기준).','Sky Sports 「Summer transfer window 2026 — Premier League deals, ins and outs」 2026-08-15 18:44 UK 갱신본 https://www.skysports.com/football/news/11095/13546618/transfer-news-summer-transfer-window-2026-premier-league-deals-ins-and-outs (실제 Chrome 전문 수집 2026-08-16)','⚠️ **완료(공식 발표) 건만**이며 진행 중 루머는 제외했다 — 루헤리·잭슨·완비사카·바르콜라·각포 등은 원장에 없다. ⚠️ **금액은 Sky 표기값**이고 구단 공시가 아니다. 애드온·셀온·급여는 포함되지 않는다 — 실제 회계 계상액과 다르다. ⛔ **임대는 금액 미표기**라 0으로 잡았다(임대료·의무매입은 별도 추적 대상). ⛔ **undisclosed는 0으로 잡지 않고 별도 카운트**한다 — 0으로 합산하면 순지출을 과소·과대 왜곡한다.',5.0);
