INSERT INTO transfer_ledger VALUES(51,'AVL','2026-summer','영입 지출','스즈키 (Parma)',29.89999999999999858,'£29.9m ≈ €30m + 애드온 €5m(총액 최대 €35m) · 5년 계약(2031) · 5년 계약(2031) — 구단 공식','Sky Sports UK(1티어) 2026-08-16 13:06 UK https://www.skysports.com/football/news/11095/13573666/aston-villa-transfer-news-zion-suzuki-lined-up-as-juventus-linked-emiliano-martinez-replacement-after-lb29-9m-deal-agreed-with-parma ; David Ornstein(1티어) 2026-08-16 10:58 UTC(€30m+최대 €35m·5년) ; Matteo Moretto(2티어) 2026-08-16 12:40 BST(€30m+€5m 구조)','⚠️⚠️ **이 행은 원장의 자체 규칙(''완료=공식 발표 건만'')에서 벗어난 유일한 예외다** — 2026-08-18 기준 **양 구단 공식 발표 0건**이고(avfc.co.uk·parmacalcio1913.com 직접 확인) 사용자 확정 지시로 등재했다. 근거 상한은 메디컬 실시(Romano 1티어)·구단 간 합의(Sky 1티어)다. 결렬 시 이 행을 제거해야 한다. ⚠️ 금액은 Sky 표기 총액이고 구단 공시가 아니다 — 애드온 €5m은 조건부라 실제 계상액과 다를 수 있다.',5.0);
